#include <bits/stdc++.h>
using namespace std;

Node* first = nullptr;
Node* last = nullptr;

void inorder(Node* node) {
    if (!node) return;
    inorder(node->left);                                                                // visit the left subtree FIRST (smaller values)
    if (last) {
        last->right = node;                                                               // link the PREVIOUSLY visited node forward to this one
        node->left = last;                                                                // and this one backward to it
    } else {
        first = node;                                                                     // the very first node visited becomes the list's head
    }
    last = node;
    inorder(node->right);                                                                 // visit the right subtree LAST (larger values)
}

Node* treeToDoublyList(Node* root) {
    if (!root) return nullptr;
    first = last = nullptr;
    inorder(root);
    last->right = first;                                                                    // close the circle: tail connects forward to head
    first->left = last;                                                                      // and head connects backward to tail
    return first;
}

int main() {
    Node* n1 = new Node(1); Node* n3 = new Node(3); Node* n5 = new Node(5);
    Node* n2 = new Node(2, n1, n3);
    Node* root = new Node(4, n2, n5);
    Node* head = treeToDoublyList(root);
    Node* node = head;
    for (int i = 0; i < 5; i++) { cout << node->val << " "; node = node->right; }
    cout << endl;
    return 0;
}
